//! Protobuf messages from Go Badger's `pb/badgerpb4.proto`.
//!
//! Written by hand with `prost` derives instead of generated by `prost-build`,
//! so building needs no `protoc`. Field tags and types must match the .proto
//! exactly; the golden tests compare encodings with Go's output.

#![allow(missing_docs)]

/// A key-value pair, used by Stream, backups and subscriptions.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Kv {
    #[prost(bytes = "vec", tag = "1")]
    pub key: Vec<u8>,
    #[prost(bytes = "vec", tag = "2")]
    pub value: Vec<u8>,
    #[prost(bytes = "vec", tag = "3")]
    pub user_meta: Vec<u8>,
    #[prost(uint64, tag = "4")]
    pub version: u64,
    #[prost(uint64, tag = "5")]
    pub expires_at: u64,
    #[prost(bytes = "vec", tag = "6")]
    pub meta: Vec<u8>,
    /// Identifies which stream the KV came from.
    #[prost(uint32, tag = "10")]
    pub stream_id: u32,
    /// Marks the end of a stream.
    #[prost(bool, tag = "11")]
    pub stream_done: bool,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct KvList {
    #[prost(message, repeated, tag = "1")]
    pub kv: Vec<Kv>,
    /// Used internally by Go for memory management.
    #[prost(uint64, tag = "10")]
    pub alloc_ref: u64,
}

/// A set of manifest changes applied atomically.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ManifestChangeSet {
    #[prost(message, repeated, tag = "1")]
    pub changes: Vec<ManifestChange>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum EncryptionAlgo {
    Aes = 0,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ManifestChange {
    /// Table id.
    #[prost(uint64, tag = "1")]
    pub id: u64,
    #[prost(enumeration = "manifest_change::Operation", tag = "2")]
    pub op: i32,
    /// Only used for CREATE.
    #[prost(uint32, tag = "3")]
    pub level: u32,
    #[prost(uint64, tag = "4")]
    pub key_id: u64,
    #[prost(enumeration = "EncryptionAlgo", tag = "5")]
    pub encryption_algo: i32,
    /// Only used for CREATE.
    #[prost(uint32, tag = "6")]
    pub compression: u32,
}

pub mod manifest_change {
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
    #[repr(i32)]
    pub enum Operation {
        Create = 0,
        Delete = 1,
    }
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Checksum {
    #[prost(enumeration = "checksum::Algorithm", tag = "1")]
    pub algo: i32,
    #[prost(uint64, tag = "2")]
    pub sum: u64,
}

pub mod checksum {
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
    #[repr(i32)]
    pub enum Algorithm {
        Crc32c = 0,
        XxHash64 = 1,
    }
}

/// An encryption key for data, itself stored encrypted with the master key.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct DataKey {
    #[prost(uint64, tag = "1")]
    pub key_id: u64,
    #[prost(bytes = "vec", tag = "2")]
    pub data: Vec<u8>,
    #[prost(bytes = "vec", tag = "3")]
    pub iv: Vec<u8>,
    #[prost(int64, tag = "4")]
    pub created_at: i64,
}

/// A prefix to match, with optional ignored positions (see [`crate::trie`]).
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Match {
    #[prost(bytes = "vec", tag = "1")]
    pub prefix: Vec<u8>,
    /// Comma separated, with dashes for ranges: "1, 2-3, 4-7, 9".
    #[prost(string, tag = "2")]
    pub ignore_bytes: String,
}
